def place(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]}).body["order_id"]


def test_unknown_customer(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_no_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_newest_first_with_discounted_totals_and_cancelled(shop):
    first = place(shop, "c2", ("LAMP", 2))  # gold: discounted
    place(shop, "c1", ("PEN", 1))  # other customer
    second = place(shop, "c2", ("BOOK", 1))
    third = place(shop, "c2", ("PEN", 2))
    shop.orders.handle_cancel(third)
    body = shop.insights.handle_order_history("c2").body
    assert body["customer_id"] == "c2"
    assert body["orders"] == [
        {"order_id": third, "status": "cancelled", "total_cents": 600},
        {"order_id": second, "status": "placed", "total_cents": 2500},
        {"order_id": first, "status": "placed", "total_cents": 10200},
    ]
    for entry in body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]


def test_lifetime_value_unknown_customer(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_no_orders(shop):
    assert shop.insights.handle_lifetime_value("c1").body == {
        "customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    place(shop, "c2", ("LAMP", 2))  # 10200 after gold discount
    place(shop, "c2", ("BOOK", 1))  # 2500
    cancelled = place(shop, "c2", ("PEN", 2))
    place(shop, "c1", ("PEN", 1))
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 12700}


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, "3", None, 1.5):
        response = shop.insights.handle_top_customers(bad)
        assert response.status == 400
        assert "error" in response.body


def test_top_customers_ranking_filtering_and_limit(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zed", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Linus", "email": "l@example.com"})
    place(shop, "c2", ("LAMP", 2))  # 10200
    place(shop, "c1", ("BOOK", 1))  # 2500
    place(shop, "c0", ("BOOK", 1))  # 2500, ties with c1; c0 sorts first
    cancelled = place(shop, "c3", ("PEN", 1))
    shop.orders.handle_cancel(cancelled)  # c3 has value 0
    body = shop.insights.handle_top_customers(10).body
    assert body["customers"] == [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 10200},
        {"customer_id": "c0", "name": "Zed", "lifetime_value_cents": 2500},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 2500},
    ]
    assert shop.insights.handle_top_customers(2).body["customers"] == body["customers"][:2]
    for entry in body["customers"]:
        value = shop.insights.handle_lifetime_value(entry["customer_id"]).body["lifetime_value_cents"]
        assert entry["lifetime_value_cents"] == value


